/**
 * Substituted at build time by `define` in vite.config.ts — true only under
 * `vite dev` with a `TYPESAFE_API_KEY` for the proxy to use. A constant, not
 * a variable: the bundler folds it away, so a production build contains no
 * Jev branch rather than a disabled one.
 */
declare const __JEV_ENABLED__: boolean;
